<?php declare(strict_types=1);require_once __DIR__.'/auth.php';$u=portal_require();$q=$db->prepare('SELECT * FROM client_portal_users WHERE id=?');$q->execute([$u['id']]);$user=$q->fetch();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare('UPDATE client_portal_users SET first_name=?,last_name=?,email=? WHERE id=?');$q->execute([trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['email']),$u['id']]);if($_POST['password']!==''){$db->prepare('UPDATE client_portal_users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$u['id']]);}$msg='Profile updated.';}$q=$db->prepare('SELECT * FROM client_portal_settings WHERE client_id=(SELECT client_id FROM client_portal_users WHERE id=?)');$q->execute([$u['id']]);$settings=$q->fetch();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4" style="max-width:700px"><a href="index.php">← Dashboard</a><h1 class="h3 mt-3">Profile & Settings</h1><?php if($msg):?><div class="alert alert-success"><?=$msg?></div><?php endif;?><form method="post"><input class="form-control mb-2" name="first_name" value="<?=htmlspecialchars($user['first_name'])?>" required><input class="form-control mb-2" name="last_name" value="<?=htmlspecialchars($user['last_name'])?>" required><input class="form-control mb-2" type="email" name="email" value="<?=htmlspecialchars($user['email'])?>" required><input class="form-control mb-3" type="password" name="password" placeholder="New password (optional)"><button class="btn btn-dark">Save</button></form></main></body></html>